#include<math.h>
typedef struct{float x,y,z;}V;
V v(float x,float y,float z){V r={x,y,z};return r;}
V a(V p,V q){return v(p.x+q.x,p.y+q.y,p.z+q.z);}
V s(V p,V q){return v(p.x-q.x,p.y-q.y,p.z-q.z);}
V m(V p,float t){return v(p.x*t,p.y*t,p.z*t);}
float d(V p,V q){return p.x*q.x+p.y*q.y+p.z*q.z;}
V q(V p){float l=sqrt(d(p,p));return v(p.x/l,p.y/l,p.z/l);}
V C=V_(0,0,0);
int Ss(V o,V e,float*t,V*n){
V o2=s(o,v(0,-.5f,-5));
float A=d(e,e),B=2*d(e,o2),K=d(o2,o2)-1;
float Q=B*B-4*A*K;
if(Q<0)return 0;
double S=sqrt((double)Q);
double t0=(-(double)B-S)/(2*(double)A);
if((float)t0>.001f){*t=(float)t0;V p=a(o,m(e,*t));*n=q(s(p,v(0,-.5f,-5)));return 1;}
double t1=(-(double)B+S)/(2*(double)A);
if((float)t1>.001f){*t=(float)t1;V p=a(o,m(e,*t));*n=q(s(p,v(0,-.5f,-5)));return 1;}
return 0;
}
int Ps(V o,V e,float*t,V*n){
if(fabsf(e.y)<1e-4f)return 0;
float t2=(-1.5f-o.y)/e.y;
if(t2<.001f)return 0;
*t=t2;*n=v(0,1,0);return 1;
}
V L;
V T(V o,V e){
float ts,tp;V ns,np;
int hs=Ss(o,e,&ts,&ns),hp=Ps(o,e,&tp,&np);
if(!hs&&!hp){
float t=(e.y+1)*.5f;
return a(m(v(.5f,.7f,1),t),m(v(1,1,1),1-t));
}
V p,n;int u;
if(hs&&hp){if(ts<tp){p=a(o,m(e,ts));n=ns;u=1;}else{p=a(o,m(e,tp));n=np;u=0;}}
else if(hs){p=a(o,m(e,ts));n=ns;u=1;}else{p=a(o,m(e,tp));n=np;u=0;}
float f=d(n,L);
if(f<0)f=0;
{V g=a(p,m(n,.001f));float t3;V n3;if(Ss(g,L,&t3,&n3))f=0;}
f=.2f+(1-.2f)*f;
if(u)return m(v(1,.2f,.2f),f);
int c=(int)(floor(p.x)+floor(p.z));
if((c&1)==0)return m(v(.9f,.9f,.9f),f);
return m(v(.4f,.4f,.4f),f);
}
int main(){
int W=2400,H=1800;
float Ww=(float)W/(float)H*2;
V U=v(Ww,0,0),J=v(0,2,0),F=v(0,0,1),O=v(0,0,0);
V UL=s(s(s(O,m(U,.5f)),m(J,.5f)),F);
L=q(v(1,1,-1));
FILE*f=fopen("reconstructed.ppm","w");
fprintf(f,"P3\n%d %d\n255\n",W,H);
for(int y=0;y<H;y++)for(int x=0;x<W;x++){
float u=(float)x/(W-1),w=(float)y/(H-1);
V E=a(a(m(J,1-w),m(U,u)),UL);
V e=q(E);
V c=T(O,e);
if(c.x<0)c.x=0;if(c.x>1)c.x=1;
if(c.y<0)c.y=0;if(c.y>1)c.y=1;
if(c.z<0)c.z=0;if(c.z>1)c.z=1;
fprintf(f,"%d %d %d\n",(int)(c.x*255.99f),(int)(c.y*255.99f),(int)(c.z*255.99f));
}
fclose(f);
}
